	//             "type": "ASK",
	//             "price": "24081.09000000",
	//             "volume": "0.07780000"
	//         },
	//         "delete_update": null,
	//         "status_update": null,
	//         "timestamp": 1660598775360
	//     }
	//  delete
	//     {
	//         "sequence": "110980825",
	//         "trade_updates": [],
	//         "create_update": null,
	//         "delete_update": {
	//             "order_id": "BXMC2CJ7HNB88U4"
	//         },
	//         "status_update": null,
	//         "timestamp": 1660598775360
	//     }
	//  trade
	//     {
	//         "sequence": "110980825",
	//         "trade_updates": [
	//             {
	//                 "base": "0.1",
	//                 "counter": "5232.00",
	//                 "maker_order_id": "BXMC2CJ7HNB88U4",
	//                 "taker_order_id": "BXMC2CJ7HNB88U5"
	//             }
	//         ],
	//         "create_update": null,
	//         "delete_update": null,
	//         "status_update": null,
	//         "timestamp": 1660598775360
	//     }
	//
	var createUpdate map[string]any = ccxt.SafeMapTyped(message, "create_update")
	var asksOrderSide any = ccxt.GetValue(orderbook, "asks")
	var bidsOrderSide any = ccxt.GetValue(orderbook, "bids")
